// PROBE (temporary): what the change log stores for a hand edit, an MCP edit
// and an in-app Agent edit.
TEST_CASE("PROBE change log by source", "[probe]")
{
    Workspace::FakeWorkspace workspace(fixture());
    Agent::ProjectPersistence persistence(workspace, {});
    Agent::AgentHost host(workspace, persistence, Agent::AgentAvailability::Unavailable, false);
    persistence.attach();
    McpDirectory directory;
    host.start_mcp(directory.path().u8string());
    const auto dump = [&](const char* when) {
        std::string text = std::string(when) + "\n";
        for (const auto& change : persistence.document().changes())
            text += "  change seq=" + std::to_string(change.seq) + " kind=" + change.kind + " actor=" + change.actor + " label=" + change.label +
                    " " + change.from + "->" + change.to + " conversation=" + change.conversation_id + " after=" + change.after_id + "\n";
        for (const auto& activity : persistence.document().activities())
            text += "  activity " + activity.tool + " source=" + (activity.source == Agent::ToolSource::Mcp ? "mcp" : "agent") +
                    " correlation=" + activity.correlation_id + " action=" + activity.action_id + "\n";
        WARN(text);
    };
    const auto patch = [&](const char* loops) {
        const auto snapshot = workspace.snapshot();
        return json{{"scope", "process"}, {"expectedSessionId", std::to_string(snapshot.session.value())},
                    {"expectedRevision", snapshot.revision}, {"changes", {{"wall_loops", loops}}}};
    };
    workspace.set_setting_for_testing("wall_loops", "3");
    dump("after a hand edit (wall_loops 3)");

    Client mcp(host.mcp()->server(), request("tools/call", {{"name", "settings_apply_patch"}, {"arguments", patch("4")}}));
    REQUIRE(wait_for([&] { return mcp.done(); }, [&] { host.pump_tools(); }));
    WARN("MCP result: " << mcp.messages().back()["result"]["structuredContent"].dump());
    dump("after an MCP settings_apply_patch (wall_loops 4)");

    const auto snapshot = workspace.snapshot();
    Client object(host.mcp()->server(), request("tools/call", {{"name", "settings_apply_patch"}, {"arguments",
        {{"scope", "object"}, {"target", {{"objectId", "21"}}}, {"expectedSessionId", std::to_string(snapshot.session.value())},
         {"expectedRevision", snapshot.revision}, {"changes", {{"wall_loops", "6"}}}}}}));
    REQUIRE(wait_for([&] { return object.done(); }, [&] { host.pump_tools(); }));
    WARN("MCP object result: " << object.messages().back()["result"]["structuredContent"].dump().substr(0, 300));
    dump("after an MCP object override (an undo step)");

    const std::string action = host.tools().propose({"settings_apply_patch", patch("5").dump()}, "in-app-message").action_id;
    for (int tick = 0; tick < 50 && !Agent::tool_state_terminal(host.tools().find(action)->state); ++tick) host.pump_tools();
    dump("after an in-app Agent settings_apply_patch (wall_loops 5)");
}
